let locale = localStorage.getItem('harvestlink-language') || 'pt';
const originals = new WeakMap();
const escape = s => s.replace(/[.*+?^${}()|[\]\\]/g,'\\$&');
export function translate(text, language=locale) {
  const entries = pairs.filter(([pt,en])=>pt!==en).map(([pt,en])=>language==='en'?[pt,en]:[en,pt]);
  const map = new Map(entries);
  const pattern = new RegExp([...map.keys()].sort((a,b)=>b.length-a.length).map(escape).join('|'),'g');
  return text.replace(pattern, match=>map.get(match));
}
export function installLanguageSwitch() {
  const wrap=document.createElement('div');wrap.className='language-switch';
  const label=document.createElement('label');label.htmlFor='language';label.textContent='Idioma / Language';
  const select=document.createElement('select');select.id='language';select.setAttribute('aria-label','Idioma / Language');select.innerHTML='<option value="pt">Português</option><option value="en">English</option>';select.value=locale;wrap.append(label,select);document.querySelector('header').append(wrap);
  function apply(){
    document.documentElement.lang=locale==='en'?'en':'pt-BR';
    const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT);let node;
    while(node=walker.nextNode()){
      if(node.parentElement.closest('script,style,pre,.bubble,.language-switch,textarea'))continue;
      const saved=originals.get(node);const original=saved&&node.nodeValue===saved.translated?saved.original:node.nodeValue;
      const translated=translate(original);originals.set(node,{original,translated});if(node.nodeValue!==translated)node.nodeValue=translated;
    }
    for(const el of document.querySelectorAll('[placeholder]')) {
      if(['message','provider-body'].includes(el.id))continue;
      const saved=originals.get(el);const original=saved&&el.placeholder===saved.translated?saved.original:el.placeholder;
      const translated=translate(original);originals.set(el,{original,translated});if(el.placeholder!==translated)el.placeholder=translated;
    }
  }
  const observer=new MutationObserver(()=>{observer.disconnect();apply();observe();});
  function observe(){observer.observe(document.body,{childList:true,subtree:true,characterData:true});}
  select.onchange=()=>{locale=select.value;localStorage.setItem('harvestlink-language',locale);observer.disconnect();apply();observe();};
  apply();observe();
}


